import unittest

from django.core.exceptions import ValidationError


class TestValidationError(unittest.TestCase):
    def test_messages_concatenates_error_dict_values(self):
        message_dict = {}
        exception = ValidationError(message_dict)
        self.assertEqual(sorted(exception.messages), [])
        message_dict['field1'] = ['E1', 'E2']
        exception = ValidationError(message_dict)
        self.assertEqual(sorted(exception.messages), ['E1', 'E2'])
        message_dict['field2'] = ['E3', 'E4']
        exception = ValidationError(message_dict)
        self.assertEqual(sorted(exception.messages), ['E1', 'E2', 'E3', 'E4'])

    def test_equality_simple_messages(self):
        self.assertEqual(ValidationError('error'), ValidationError('error'))

    def test_equality_list_messages_order_independent(self):
        self.assertEqual(
            ValidationError(['error1', 'error2']),
            ValidationError(['error2', 'error1'])
        )

    def test_equality_dict_messages_order_independent(self):
        self.assertEqual(
            ValidationError({'field1': ['error1', 'error2']}),
            ValidationError({'field1': ['error2', 'error1']})
        )

    def test_equality_dict_field_order_independent(self):
        self.assertEqual(
            ValidationError({'field1': ['error1'], 'field2': ['error2']}),
            ValidationError({'field2': ['error2'], 'field1': ['error1']})
        )

    def test_inequality_different_messages(self):
        self.assertNotEqual(ValidationError('error1'), ValidationError('error2'))

    def test_inequality_different_types(self):
        self.assertNotEqual(ValidationError('error'), 'error')

    def test_hash_consistency(self):
        self.assertEqual(hash(ValidationError('error')), hash(ValidationError('error')))
        self.assertEqual(
            hash(ValidationError(['error1', 'error2'])),
            hash(ValidationError(['error2', 'error1']))
        )
        self.assertEqual(
            hash(ValidationError({'field1': ['error1', 'error2']})),
            hash(ValidationError({'field1': ['error2', 'error1']}))
